const { readFileSync, writeFileSync, existsSync } = require('fs');
const snapshotPath = 'C:\\myapp\\api-snapshot.json';

// ✅ Only compare the body, ignore headers/date
const raw = $input.first().json;
const bodyOnly = raw.body || raw;  // HTTP Request puts body in .body
const current = JSON.stringify(bodyOnly, null, 2);

if (!existsSync(snapshotPath)) {
  writeFileSync(snapshotPath, current);
  return [{ json: {
    status: 'CREATED',
    message: 'First snapshot saved.',
    snapshot: current
  }}];
}

const previous = readFileSync(snapshotPath, 'utf8');

if (current === previous) {
  return [{ json: {
    status: 'MATCH',
    message: 'API response unchanged.',
    snapshot: current
  }}];
} else {
  return [{ json: {
    status: 'DIFF',
    message: 'API response has changed!',
    previous: previous,
    current: current
  }}];
}

const puppeteer = require('puppeteer');
const { writeFileSync, existsSync, readFileSync } = require('fs');

const screenshotPath = 'C:\\myapp\\current-screenshot.png';
const snapshotPath   = 'C:\\myapp\\saved-screenshot.png';
const logPath        = 'C:\\myapp\\snapshot-log.txt';

const browser = await puppeteer.launch({
  headless: true,
  executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
  args: [
    '--no-sandbox',
    '--disable-setuid-sandbox',
    '--disable-gpu',
    '--disable-dev-shm-usage'
  ]
});

const page = await browser.newPage();
await page.setViewport({ width: 1280, height: 720 });
await page.goto('http://localhost:3000', { waitUntil: 'networkidle0' });

const screenshot = await page.screenshot({ fullPage: true });
await browser.close();

writeFileSync(screenshotPath, screenshot);

if (!existsSync(snapshotPath)) {
  writeFileSync(snapshotPath, screenshot);
  const line = `${new Date().toISOString()} | Screenshot: CREATED ✅\n`;
  writeFileSync(logPath, line, { flag: 'a' });
  return [{ json: { 
    status: 'CREATED', 
    message: 'First screenshot snapshot saved!',
    path: screenshotPath
  }}];
}

const saved  = readFileSync(snapshotPath);
const isSame = Buffer.compare(saved, screenshot) === 0;

const line = `${new Date().toISOString()} | Screenshot: ${isSame ? 'MATCH ✅' : 'DIFF ⚠️'}\n`;
writeFileSync(logPath, line, { flag: 'a' });

if (isSame) {
  return [{ json: { 
    status: 'MATCH', 
    message: 'Screenshot unchanged ✅',
    path: screenshotPath
  }}];
} else {
  writeFileSync(snapshotPath, screenshot);
  return [{ json: { 
    status: 'DIFF', 
    message: 'Screenshot changed ⚠️ snapshot updated',
    path: screenshotPath
  }}];
}

const { appendFileSync, writeFileSync } = require('fs');
const d = $input.first().json;

appendFileSync('C:\\myapp\\snapshot-log.txt',
  `${new Date().toISOString()} | API: DIFF ⚠️ | API response changed!\n`
);

// Update snapshot to new value so next run is clean
writeFileSync('C:\\myapp\\api-snapshot.json', d.current);

return [{ json: {
  status: 'API DIFF ⚠️',
  message: 'API changed — snapshot updated',
  previous: d.previous,
  current: d.current
}}];
